// E2E for feature answer-feedback, against the built app (run `npm run build` first).
// Usage: node --experimental-websocket scripts/e2e/answer-feedback.mjs
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { withApp, pageHelpers, report } from './app-session.mjs';

const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-e2e-feedback-'));
const checks = [];
try {
  const first = await withApp({ dataDir }, async ({ evaluate, waitFor }) => {
    await evaluate(pageHelpers);
  // Restart the app on the same data dir.
  await withApp({ dataDir }, async ({ evaluate }) => {
    const list = await evaluate(`window.knowledgeBase.feedback.list()`);
    checks.push(['after restart feedback.list() still has both ratings',
      list.length === 2 &&
        list.some((f) => f.answerId === first.a.id && f.rating === 'up') &&
        list.some((f) => f.answerId === first.uiAnswerId && f.rating === 'down'), list]);
  });
} finally {
  fs.rmSync(dataDir, { recursive: true, force: true });
}
report('answer-feedback e2e', checks);
